 IF md5(pg_get_functiondef('smarter_private.record_rakeback_payer_contracts()'::regprocedure)) IS DISTINCT FROM '82ca3dd2e58a1601f38749ac67105197' THEN RAISE EXCEPTION 'confirmed_payer_preimage_changed';END IF;
