 IF before_meta->>0 IS DISTINCT FROM('postgres'::regrole::oid)::text OR(before_meta-0)IS DISTINCT FROM('["16384", ["postgres=X/postgres"], true, "v", ["search_path=pg_catalog, public"], "u", false]'::jsonb-0) THEN RAISE EXCEPTION 'confirmed_payer_metadata_changed' USING DETAIL=before_meta::text;END IF;
 EXECUTE $definition$CREATE OR REPLACE FUNCTION smarter_private.record_rakeback_payer_contracts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 PERFORM smarter_private.ensure_rakeback_payer_contracts(NEW.id);
 RETURN NULL;
END $function$
